def classify(q):
    text = q.get('question', q.get('q', '')) + " " + q.get('explanation', q.get('exp', '')) + " " + " ".join(q.get('options', q.get('opts', [])))
    for ch_id, kws in RULES:
        for kw in kws:
            if kw.lower() in text.lower():
                return ch_id
    return q.get('blueprint_chapter_id', 'bio_bot_01')

reclassified = Counter()
for q in bio_questions:
    new_ch = classify(q)
    reclassified[new_ch] += 1

print("Reclassified chapter counts:")
for ch, count in sorted(reclassified.items()):
    print(f"  {ch}: {count}")

